const PROMPT_WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

const PROMPT_RULES = `You turn a personal finance message (Indonesian or English) or a receipt photo into structured transactions for one user in Jakarta. Currency is IDR. Return JSON only, matching the schema.

Amounts: whole rupiah, always positive; direction comes from "type". "25rb" or "25k" = 25000, "1,5jt" = 1500000, "ceban" = 10000, "goceng" = 5000.
Dates and times: first match wins: (a) a date or time written in the message ("kemarin", "tadi pagi", "tgl 28 jam 8", "28/10 19.30"), resolved against the message time below; (b) the date and time printed on the receipt or statement; (c) otherwise leave txn_date and txn_time null. Use YYYY-MM-DD and 24h HH:MM. Never use today's processing time. A date without a month or year ("tgl 28") means the most recent such date on or before the message date, never a future one.
Account: default account unless the message names one. "cash" or "tunai" means Cash. A named account wins.
Types: "expense" is money spent, "income" is money received, "transfer" moves money between two own accounts (account = from, to_account = to).
Transfer fee: if a fee is stated or visible, put it in "fee" (whole rupiah) and keep it out of "amount": amount is the money sent, without the fee. Do not add a separate transaction for the fee. Never guess a fee; use 0 when none.
ATM withdrawal is a transfer from the bank account to Cash. Investing (e.g. buying VOO) is a transfer to Investment, never an expense.
E-wallet top-up (GoPay, OVO, Dana...) is an expense. When the message says what the top-up is for ("buat gojek", "untuk makan"), the category is that purpose and not e-wallet top-up: "topup gopay 50rb buat gojek" is the transport category. Use the e-wallet top-up category only when no purpose is given. There are no e-wallet accounts.
Category: choose only from the list, using aliases as hints. For transfers set category_id null. For income use an income category; freelance income is the IDR amount that actually reached the bank, category freelance.
Nature: every expense gets "need" or "want", never null. "#need" or "#want" in the text decides it; otherwise use the category default when it has one; otherwise decide yourself. Null for income and transfers.
Irregular: true when the text has "#irregular" or the expense is annual by nature (pajak motor, STNK, yearly service, annual fee, insurance premium paid yearly); otherwise false.
merchant: shop or payee when known, else null. note: 1-3 words describing the purchase, else null.
confidence: 0 to 1, how sure you are about the whole transaction.
Never invent an amount: when the message states no amount, set amount to 0 and add "amount" to "missing". Leave "missing" empty when the amount is stated. Use reply_hint for one short note about anything ambiguous, else null.
One transaction per payment. A receipt photo is one transaction.`;

const PROMPT_PHOTO_RULES = `Photo rules: read the receipt or screenshot. Fill "items" with every line item (no from 1, name, price, selected true), and "receipt" with subtotal, tax, service, discount and total (0 when absent). Without a caption the user paid the full total: amount = total. Use the printed payment method for the account: CASH or TUNAI is Cash; DEBIT or QRIS with a bank name is that bank; unknown is the default account. Use the date and time printed on the receipt. Bank or e-wallet screenshots (transfer, QRIS, payment success): money sent to another person or a merchant is an expense from the bank whose app is shown, merchant = the recipient name, category from the caption or remarks, otherwise the others category; it is a "transfer" only when the caption names one of the user's own accounts as the destination. "IDR 100,000.00" and "Rp 100.000,00" both mean 100000: the two digits after the last separator are cents, drop them. An admin fee shown on the screenshot goes in "fee", and amount is the nominal without it. A screenshot of a transaction list (account activity or history: several rows, each with its own date, name and amount) is one transaction per row, top to bottom: never skip, merge or reorder rows, and copy every name and amount exactly as printed. Skip only rows marked failed, pending or cancelled. Money sent or paid is an expense, money received is income. A row that sends money to a person ("Transfer to BCA Account" under a name) is an expense with merchant = that name, never a transfer to Cash; a person's name alone says nothing about the category, so use the others category for it. For these rows set items to [] and receipt to null, and txn_time to null unless a time is printed on the row (the clock in the phone status bar is not a transaction time). Never guess a row: when a row is too small or blurred to read, leave it out and say in reply_hint how many rows were left out. When a printed date has no legible year, use the year of the message time. For text messages set items to [] and receipt to null.`;

function promptTrue(x) {
  return x === true || String(x).toUpperCase() === 'TRUE';
}

function promptJakarta(iso) {
  const ms = Date.parse(iso);
  if (isNaN(ms)) return String(iso);
  const d = new Date(ms + 7 * 3600000);
  return `${d.toISOString().slice(0, 10)} ${d.toISOString().slice(11, 16)} (${PROMPT_WEEKDAYS[d.getUTCDay()]})`;
}

function promptObj(props) {
  return { type: 'object', properties: props, required: Object.keys(props), additionalProperties: false };
}

function promptSchema(catIds, accNames) {
  const str = { type: ['string', 'null'] };
  const int = { type: 'integer' };
  const txn = promptObj({
    type: { type: 'string', enum: ['expense', 'income', 'transfer'] },
    amount: int,
    account: { type: 'string', enum: accNames },
    to_account: { type: ['string', 'null'], enum: [...accNames, null] },
    category_id: { type: ['string', 'null'], enum: [...catIds, null] },
    nature: { type: ['string', 'null'], enum: ['need', 'want', null] },
    merchant: str,
    note: str,
    txn_date: str,
    txn_time: str,
    fee: int,
    irregular: { type: 'boolean' },
    items: {
      type: 'array',
      items: promptObj({ no: int, name: { type: 'string' }, price: int, selected: { type: 'boolean' } }),
    },
    receipt: {
      anyOf: [promptObj({ subtotal: int, tax: int, service: int, discount: int, total: int }), { type: 'null' }],
    },
    confidence: { type: 'number' },
  });
  return promptObj({
    transactions: { type: 'array', items: txn },
    missing: { type: 'array', items: { type: 'string' } },
    reply_hint: str,
  });
}

function buildLlmRequest({ kind, text, imageDataUrl, msgDate, categories, accounts, model }) {
  const cats = categories.filter((c) => promptTrue(c.active));
  const catLines = cats.map(
    (c) => `${c.id} | ${c.group} | ${c.name} | ${c.type} | default_nature: ${c.default_nature || '-'} | aliases: ${c.aliases || '-'}`,
  );
  const accLines = accounts.map((a) => a.account + (promptTrue(a.is_default) ? ' (default)' : ''));
  const photo = kind === 'photo';
  const system = [
    PROMPT_RULES,
    photo ? PROMPT_PHOTO_RULES : '',
    `Message time (Asia/Jakarta): ${promptJakarta(msgDate)}`,
    `Categories (id | group | name | type | default nature | aliases):\n${catLines.join('\n')}`,
    `Accounts:\n${accLines.join('\n')}`,
  ]
    .filter(Boolean)
    .join('\n\n');
  const content = photo
    ? [
        { type: 'text', text: text || '(no caption)' },
        { type: 'image_url', image_url: { url: imageDataUrl } },
      ]
    : text;
  return {
    model,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content },
    ],
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'parsed_entry',
        strict: true,
        schema: promptSchema(
          cats.map((c) => c.id),
          accounts.map((a) => a.account),
        ),
      },
    },
  };
}
// A scrolling screenshot: Telegram shrinks the long side to 1280 px, so the longer the capture, the
// smaller the text. Seen live with a BCA activity list: 14 rows at ratio 4.7 (about 270 px wide) were
// all read, about 21 rows at ratio 6.7 (about 190 px wide) came back as 3 made-up rows.
const IMAGE_MAX_RATIO = 5;

// {width, height} from the JPEG frame header, or null when the data is not a readable JPEG
function imageJpegSize(base64) {
  const b = Buffer.from(String(base64 || ''), 'base64');
  if (b.length < 4 || b[0] !== 0xff || b[1] !== 0xd8) return null;
  let i = 2;
  while (i + 9 < b.length) {
    if (b[i] !== 0xff) return null;
    const marker = b[i + 1];
    if (marker === 0xff) {
      i += 1; // fill byte
      continue;
    }
    // SOF0..SOF15 hold the size; C4 (huffman), C8 (reserved) and CC (arithmetic) are not frames
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      return { height: b.readUInt16BE(i + 5), width: b.readUInt16BE(i + 7) };
    }
    i += 2 + b.readUInt16BE(i + 2);
  }
  return null;
}

function imageTooLong(size) {
  return !!size && size.width > 0 && size.height / size.width > IMAGE_MAX_RATIO;
}
const MSG_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function fmtRp(n) {
  const v = Math.round(Number(n) || 0);
  return (v < 0 ? '-' : '') + 'Rp' + String(Math.abs(v)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

function fmtDate(d) {
  const [y, m, day] = String(d).slice(0, 10).split('-').map(Number);
  return MSG_MONTHS[m - 1] ? `${day} ${MSG_MONTHS[m - 1]} ${y}` : String(d);
}

// '2026-11' -> 'Nov 2026'
function msgMonth(ym) {
  const [y, m] = String(ym).split('-').map(Number);
  return `${MSG_MONTHS[m - 1]} ${y}`;
}

function msgPlural(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

function msgLine(r, names) {
  const review = r.status === 'needs_review';
  const parts = [fmtRp(r.amount)];
  if (r.type === 'transfer') parts.push(`${r.account} → ${r.to_account}`);
  else parts.push(names[r.category_id] || r.category_id, r.account);
  const label = r.note || r.merchant;
  if (label) parts.push(`"${label}"`);
  if (r.nature) parts.push(r.nature);
  return `${review ? '⚠️' : '✅'} ${parts.join(' · ')}  (#${r.id})${review ? ' · needs review' : ''}`;
}

// One entry on one line for /review and /last: mark, id, date, amount, where, label
function msgBrief(r) {
  const mark = r.status === 'needs_review' ? '⚠️' : '✅';
  const where = r.type === 'transfer' ? `${r.account} → ${r.to_account}` : `${r.category_id} · ${r.account}`;
  const label = r.merchant || r.note;
  return `${mark} #${r.id} · ${fmtDate(r.txn_date)} · ${fmtRp(r.amount)} · ${where}${label ? ` · "${label}"` : ''}`;
}

const MSG_LIST_MAX = 30;

function msgList(rows) {
  const lines = rows.slice(0, MSG_LIST_MAX).map(msgBrief);
  if (rows.length > MSG_LIST_MAX) lines.push(`… and ${rows.length - MSG_LIST_MAX} more`);
  return lines;
}

const MSG = {
  // rows: Transactions row objects of one batch; categories: Categories rows (for names)
  saved(rows, categories) {
    const names = {};
    for (const c of categories || []) names[c.id] = c.name;
    return rows.map((r, i) => msgLine(r, names) + (i === rows.length - 1 ? ' · /undo' : '')).join('\n');
  },
  askAmount(text) {
    const eg = text ? `${text} 18rb` : '18rb';
    return `❓ How much was it? Reply with the amount, e.g. "${eg}".`;
  },
  askMissing(missing, hint) {
    const what = (missing || []).join(', ');
    return `❓ I need a bit more info${what ? `: ${what}` : ''}.${hint ? ` ${hint}` : ''} Please send it again with the details.`;
  },
  reviewOldDate(date) {
    return `Check the date: ${fmtDate(date)} is more than two months back.`;
  },
  reviewOpening(account, openingDate) {
    return `Check: dated on or before the ${account} opening balance (${fmtDate(openingDate)}), so it may be counted twice. /undo if so.`;
  },
  reviewTransfer(account) {
    return `Check: saved as a transfer to your own ${account}. If you paid someone else, /undo and send it again with a caption, e.g. "bayar utang 100rb".`;
  },
  photoTooLong() {
    return '❓ This screenshot is too long to read: Telegram shrinks it and the text gets too small. Nothing was saved. Send shorter screenshots instead, about two screens each.';
  },
  futureDate() {
    return '❓ That date is in the future. For upcoming payments, add a rule in the Recurring tab.';
  },
  badAccount(name, accounts) {
    const list = (accounts || []).map((a) => a.account).join(', ');
    return `❓ I don't know the account "${name}". Accounts: ${list}.`;
  },
  badCategory(id) {
    return `❓ The category "${id}" is missing or inactive. Check the Categories tab, then send it again.`;
  },
  needToAccount() {
    return '❓ Which account did the money go to? Send it again with the destination account.';
  },
  sameAccount() {
    return '❓ A transfer needs two different accounts. Send it again with the right ones.';
  },
  error(text, reason) {
    const what = text ? `"${text}"` : 'your message';
    return `🔴 Couldn't process ${what} (${reason || 'the AI service did not respond'}). Please send it again.`;
  },
  pending(n) {
    return `📥 Processing ${msgPlural(n, 'pending message', 'pending messages')}`;
  },
  reviewHint() {
    return 'All correct? Send /ok. Otherwise /review shows how to fix them.';
  },
  reviewList(rows) {
    return [
      `⚠️ ${msgPlural(rows.length, 'entry needs', 'entries need')} review`,
      ...msgList(rows),
      'All correct: /ok · some correct: /ok 16 25 · wrong: /undo 25, then send that one again as text.',
    ].join('\n');
  },
  reviewNone() {
    return 'Nothing needs review.';
  },
  confirmed(ids) {
    return `✅ Confirmed ${msgPlural(ids.length, 'entry', 'entries')} (${ids.map((i) => '#' + i).join(', ')}).`;
  },
  // what: 'void' for /undo, 'confirm' for /ok
  badIds(tokens, what) {
    const why = what === 'confirm' ? 'not found or not waiting for review' : 'not found or already void';
    return `❓ Nothing changed: ${tokens.join(', ')} ${why}. Send /${what === 'confirm' ? 'review' : 'last'} to see the ids.`;
  },
  last(rows) {
    return rows.length ? ['Latest entries', ...msgList(rows)].join('\n') : 'No entries yet.';
  },
  voided(ids) {
    return `↩️ Voided ${msgPlural(ids.length, 'entry', 'entries')} (${ids.map((i) => '#' + i).join(', ')}).`;
  },
  nothingToVoid() {
    return 'Nothing to void.';
  },
  // accounts: [{account, balance}], liquidTotal: number
  balance(accounts, liquidTotal) {
    const lines = accounts.map((a) => `${a.account} · ${fmtRp(a.balance)}`);
    return ['Balance', ...lines, `Liquid total · ${fmtRp(liquidTotal)}`].join('\n');
  },
  summaryUsage() {
    return '❓ Which month? Send "/summary" for this month or e.g. "/summary 2026-10".';
  },
  summaryEmpty(month) {
    return `No entries in ${msgMonth(month)}.`;
  },
  // d: the totals built by cSummary (commands.js)
  summary(d) {
    const pct = (n) => `${d.expense ? Math.round((n / d.expense) * 100) : 0}%`;
    const pairs = (list) => list.map((x) => `${x.name} ${fmtRp(x.amount)}`).join(' · ');
    const out = [
      `Summary · ${msgMonth(d.month)}${d.to ? ` (to ${fmtDate(d.to)})` : ''}`,
      `Income · ${fmtRp(d.income)}`,
      `Expense · ${fmtRp(d.expense)}`,
      `Net · ${fmtRp(d.income - d.expense)}`,
    ];
    if (d.expense) {
      out.push('', 'Expense by group');
      for (const g of d.groups) {
        out.push(`${g.name} · ${fmtRp(g.amount)} · ${pct(g.amount)}`);
        for (const s of g.subs) out.push(`   ${s.name} · ${fmtRp(s.amount)}`);
      }
      const unset = d.expense - d.need - d.want;
      out.push('', 'Need vs want', `Need · ${fmtRp(d.need)} · ${pct(d.need)}`, `Want · ${fmtRp(d.want)} · ${pct(d.want)}`);
      if (unset) out.push(`Not set · ${fmtRp(unset)} · ${pct(unset)}`);
      if (d.want) {
        out.push(`Top want · ${pairs(d.topWant)}`);
        out.push(`Want by day · weekday ${fmtRp(d.wantWeekday)} · weekend ${fmtRp(d.wantWeekend)}`);
        if (d.wantTimes.length) out.push(`Want by time · ${pairs(d.wantTimes)}`);
      }
    }
    if (d.irregular.length || d.irregularAvg) {
      out.push('', 'Irregular');
      for (const r of d.irregular) out.push(`${fmtDate(r.txn_date)} · ${fmtRp(r.amount)} · ${r.name}${r.label ? ` · "${r.label}"` : ''}`);
      out.push(`12-month average · ${fmtRp(d.irregularAvg)} a month`);
    }
    out.push('', `Freelance income · ${fmtRp(d.freelance)}`);
    if (d.review) out.push(`⚠️ ${msgPlural(d.review, 'entry needs', 'entries need')} review · /review`);
    out.push(`Liquid total · ${fmtRp(d.liquid)}`);
    const span = `the last ${msgPlural(d.fullMonths, 'full month', 'full months')}`;
    if (!d.fullMonths) out.push('Runway · not enough history yet (needs one full month of entries)');
    else if (!d.needAvg) out.push(`Runway · no "need" spending in ${span}`);
    else out.push(`Runway · ${(d.liquid / d.needAvg).toFixed(1)} months ("need" spending ${fmtRp(d.needAvg)} a month over ${span})`);
    return out.join('\n');
  },
  cashAdjusted(real, diff, id) {
    return `✅ Cash set to ${fmtRp(real)}. Logged ${fmtRp(Math.abs(diff))} as unrecorded cash (#${id}) · /undo`;
  },
  cashMatches(real) {
    return `Cash matches at ${fmtRp(real)}. Nothing to log.`;
  },
  cashUsage() {
    return '❓ How much cash do you have? Send e.g. "/cash 150000".';
  },
  help() {
    return [
      'Send a message or a receipt photo to log an entry, e.g. "makan padang 25rb".',
      '/undo · void the last entry, or one by id, e.g. /undo or /undo 25',
      '/last · show the latest entries, e.g. /last or /last 10',
      '/review · list entries that need review, e.g. /review',
      '/ok · confirm entries that need review, e.g. /ok or /ok 16 25',
      '/summary · show a month in numbers, e.g. /summary or /summary 2026-10',
      '/balance · show account balances, e.g. /balance',
      '/cash <amount> · set real cash, e.g. /cash 150000',
      '/help · show this list, e.g. /help',
    ].join('\n');
  },
  unknownCommand() {
    return "Unknown command. Send /help to see what's available.";
  },
  nudge(n) {
    return `${msgPlural(n, 'entry', 'entries')} today. Anything missing?`;
  },
};
